steps.script:
# Visit 1: open the Plan Editor.
var m = tree.current_scene
var army = -1
for i in range(m.army_options.size()):
	if str(m.army_options[i].id) == "recon_stomps":
		army = i
m.player1_dropdown.selected = army
m.player1_dropdown.emit_signal("item_selected", army)
var zone = -1
for i in range(m.plan_editor_zone_dropdown.item_count):
	if m.plan_editor_zone_dropdown.get_item_text(i).begins_with("Hammer"):
		zone = i
if zone < 0:
	return "zone picker empty"
m.plan_editor_zone_dropdown.selected = zone
return "ready"

# Leave the way a player does — the banner's own Exit to Menu button.
var btn = tree.root.find_child("PlanEditorExitButton", true, false)
if btn == null:
	return "exit button missing"
btn.emit_signal("pressed")
return "pressed"

# The second session must be a fresh army, not the first one's leftovers.
var own = 0
for uid in GameState.state.units.keys():
	if int(GameState.state.units[uid].get("owner", 0)) == 1:
		own += 1
var enemy = 0
for uid in GameState.state.units.keys():
	if int(GameState.state.units[uid].get("owner", 0)) == 2:
		enemy += 1
print("SCENARIO pm11 second editor session: %d own units, %d enemy units" % [own, enemy])
return "%d|%d" % [own, enemy]

var btn = tree.root.find_child("PlanEditorExitButton", true, false)
if btn == null:
	return "exit button missing"
btn.emit_signal("pressed")
return "pressed"

# Visit 1 of the simulator.
var sim = tree.root.get_node_or_null("PlanSimulatorUI")
if sim == null:
	return "no PlanSimulatorUI autoload"
sim.open()
return "opened"

var sim = tree.root.get_node_or_null("PlanSimulatorUI")
sim.close()
return "closed"

var sim = tree.root.get_node_or_null("PlanSimulatorUI")
var runner = tree.root.get_node_or_null("PlanSimulator")
var running = false
if runner != null and runner.has_method("is_running"):
	running = runner.is_running()
print("SCENARIO pm11 simulator second visit: visible=%s running=%s" % [str(sim.visible), str(running)])
return "%s|%s" % [str(sim.visible), str(running)]

var sim = tree.root.get_node_or_null("PlanSimulatorUI")
sim.close()
return "closed"
